def comps_of(g,sr,sc_):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 or (i in sr) or (j in sc_): continue
            if (i,j) in seen: continue
            st=[(i,j)]; seen.add((i,j)); c=[]
            while st:
                y,x=st.pop(); c.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and g[ny][nx]!=0 and (ny not in sr) and (nx not in sc_) and (ny,nx) not in seen:
                        seen.add((ny,nx)); st.append((ny,nx))
            out.append(c)
    return out
def bands_of(rows,H):
    b=[]; cur=None
    for i in range(H):
        if i in rows and cur is None: cur=[]
        elif i in rows and cur is not None: b.append(cur); cur=None
        else:
            if cur is None: cur=[i]
            else: cur.append(i)
    if cur: b.append(cur)
    return b
